const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',posts:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h4',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h1 M12 14h1 M16 14h1 M8 17h1 M12 17h1',channels:'M3 4h7v7H3z M14 4h7v7h-7z M3 15h7v6H3z M14 15h7v6h-7z',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',limits:'M4 19V9 M10 19V4 M16 19v-7 M22 19V7',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 7 M22 21v-3a4 4 0 0 0-3-4',settings:'M9 3h6l1 4 4 1v8l-4 1-1 4H9l-1-4-4-1V8l4-1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',back:'M19 12H5 M11 6l-6 6 6 6',arrow:'M5 12h14 M13 6l6 6-6 6',refresh:'M20 7v5h-5 M4 17v-5h5 M5 8a8 8 0 0 1 13-3l2 3 M4 16l2 3a8 8 0 0 0 13-3',close:'M6 6l12 12 M6 18L18 6',plus:'M12 5v14 M5 12h14',image:'M3 3h18v18H3z M3 17l6-6 5 5 3-3 4 4 M16 7h.01',check:'M5 12l4 4L19 6',play:'M7 4l14 8-14 8z',stop:'M5 5h14v14H5z',send:'M22 2L9 15 M22 2l-6 20-7-7-7-7z',account:'M9 4h6v5l4 3v9H5v-9l4-3z M9 16h6',log:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h6',menu:'M4 6h16 M4 12h16 M4 18h16',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',star:'M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',logout:'M9 3H3v18h6 M14 7l5 5-5 5 M8 12h11'};
Object.assign(icons,{bell:'M18 8a6 6 0 0 0-12 0v6l-2 3h16l-2-3z M10 21h4',sun:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5.6 5.6l1.4 1.4 M17 17l1.4 1.4 M5.6 18.4l1.4-1.4 M17 7l1.4-1.4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M9 5h12 M9 12h12 M9 19h12 M3 5h1 M3 12h1 M3 19h1',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',chevron:'M9 5l7 7-7 7'});
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.posts}"/></svg>`;
const fmt=ts=>ts?new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(ts*1000)):'Время не назначено';
const num=x=>Number(x||0).toLocaleString('ru-RU');
const plural=(n,forms)=>forms[n%100>=11&&n%100<=14?2:n%10===1?0:n%10>=2&&n%10<=4?1:2];
const stateNames={pending:'На проверке',draft:'Черновик',approved:'В очереди',sent:'Опубликован',publishing:'Отправляется',unknown:'Проверить результат',rejected:'Отклонён',new:'В очереди',preparing:'Идёт поиск',cancelled:'Остановлен',failed:'Завершён с ошибкой',checking:'Проверка групп',active:'Работает',stopped:'Остановлена',done:'Готово',queued:'В очереди',running:'Идёт поиск',sending:'Отправляется',skipped:'Пропущено'};
const badge=(s,label)=>`<span class="badge ${['sent','done','active'].includes(s)?'green':['unknown','failed'].includes(s)?'red':['preparing','publishing','checking','running'].includes(s)?'orange':['draft','stopped','cancelled','rejected'].includes(s)?'gray':''}">${esc(label||stateNames[s]||s)}</span>`;
const btn=(label,action,cls='',attrs='')=>`<button ${attrs.includes('type=')?'':'type="button"'} class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const navBtn=(label,nav,cls='')=>`<button class="btn ${cls}" data-nav="${nav}">${label}</button>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">${icon('posts')}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;
const field=(label,name,value='',type='text',help='')=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0"':''}>${help?`<p class="help">${help}</p>`:''}`;
const area=(label,name,value='',help='')=>`<label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea>${help?`<p class="help">${help}</p>`:''}`;
let S=null,section='smm',filter='pending',channelFilter='all',proposalView='list',calendarDay='all',query='',lastRoute='',busy=false,modalOpener=null,connected=true,refreshing=false,dataSignature='';
try{section=localStorage.getItem('studio-section')==='manager'?'manager':'smm';}catch{}
try{const view=localStorage.getItem('studio-proposal-view');if(['gallery','list'].includes(view))proposalView=view;}catch{}
const routes={posts:'Лента',more:'Ещё',notifications:'Уведомления',calendar:'Календарь',channels:'Мои каналы',search:'Поиск постов',limits:'Расход и лимиты',campaigns:'Рассылки',partners:'Партнёры',account:'Аккаунт отправителя',log:'Журнал отправок',team:'Команда',settings:'Настройки'};
const smmRoutes=['posts','calendar','channels','more','search','limits'],mgrRoutes=['campaigns','partners','account','log'];
const route=()=>routes[location.hash.slice(1)]?location.hash.slice(1):'posts';
function hydrateIcons(){$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.classList.toggle('error-toast',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,error?7500:4000);}
function closeModal(){$('#shell').inert=false;$('#login').inert=false;$('#modal').hidden=true;$('#modal-body').replaceChildren();document.body.style.overflow='';modalOpener?.focus?.();}
function modal(title,body,label='СТУДИЯ'){$('.modal').classList.remove('preview-modal');modalOpener=document.activeElement;$('#modal-title').textContent=title;$('#modal-label').textContent=label;$('#modal-body').innerHTML=body;$('#modal').hidden=false;$('#shell').inert=true;$('#login').inert=true;document.body.style.overflow='hidden';hydrateIcons();}
// Focus stays inside the dialog; Escape closes it and returns focus to its button.
function focusModal(){setTimeout(()=>$('#modal-body input, #modal-body textarea, #modal-body button, #modal .icon-btn')?.focus(),0);}
async function api(path,body,method='POST'){
 if(method!=='GET'&&!connected&&path!=='/api/login')throw new Error('Нет соединения. Дождись восстановления.');
 const headers={'X-SMM-Web':'1'}; if(S?.csrf)headers['X-CSRF-Token']=S.csrf;
 let payload=body;
 if(!(body instanceof FormData)&&method!=='GET'){headers['Content-Type']='application/json';payload=JSON.stringify(body||{});}
 let response;try{response=await fetch(path,{method,headers,credentials:'same-origin',body:method==='GET'?undefined:payload,signal:AbortSignal.timeout(40000)});}catch{throw new Error('Не удалось связаться с сервером. Проверь состояние перед повтором действия.');}
 let result;try{result=await response.json();}catch{throw new Error('Сервер вернул некорректный ответ. Проверь журнал.');}
 if(response.status===401&&path!=='/api/login'){showLogin();throw new Error(result.error||'Сессия завершилась.');}
 if(!response.ok)throw new Error(result.error||'Действие не выполнено.');return result;
}
function showLogin(){$('#boot-splash').hidden=true;S=null;$('#shell').hidden=true;$('#login').hidden=false;closeModal();$('#connection-banner').hidden=true;}
async function load(renderPage=true,onlyChanged=false){if(refreshing)return;refreshing=true;try{const next=await api('/api/state',null,'GET'),signature=JSON.stringify({...next,now:0,cooldown_active:next.cooldown>next.now}),changed=signature!==dataSignature;S=next;dataSignature=signature;connected=true;$('#connection-banner').hidden=true;$('#boot-splash').hidden=true;$('#login').hidden=true;$('#shell').hidden=false;$('#version').textContent='Версия '+S.version;if(renderPage&&(!onlyChanged||changed))render();$('#sync-state').textContent='Обновлено '+new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}).format(new Date());}catch(e){if(S){connected=false;$('#connection-banner').hidden=false;}else if(!$('#login').hidden){/* login already displayed */}else showLogin();if(renderPage&&S)toast(e.message,true);}finally{refreshing=false;}}
async function mutate(path,body,message='Сохранено'){await api(path,body);await load(false);if(S)render();if(message)toast(message);}
function syncSidebar(){$('#sidebar').inert=window.matchMedia('(max-width:700px)').matches&&!$('#sidebar').classList.contains('open');}
function go(r){closeModal();$('#sidebar').classList.remove('open');$('#scrim').hidden=true;syncSidebar();if(location.hash==='#'+r)render();else location.hash=r;}
function switchSection(which){section=which;try{localStorage.setItem('studio-section',section);}catch{};go(section==='smm'?'posts':'campaigns');}
function header(title,desc,action='',eyebrow=section==='smm'?'СММ / КОНТЕНТ':'МЕНЕДЖЕР / ПРОДВИЖЕНИЕ'){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function pauseNotice(){return S.paused?`<div class="notice"><span>${icon('stop')}</span><div class="grow"><strong>СММ на паузе.</strong> ${esc(S.pause_reason||'Проверь настройки перед запуском.')} Поиск и публикации остановлены.</div>${btn('Продолжить','resume','small')}</div>`:'';}
function stats(items){return `<div class="stats">${items.map(([name,value,desc,i])=>`<div class="stat"><div class="stat-top"><span>${name}</span><span class="stat-icon">${icon(i)}</span></div><div class="stat-value ${String(value).length>9?'stat-text':''}">${value}</div><small>${desc}</small></div>`).join('')}</div>`;}
function mediaSrc(p){if(!p.media)return '';try{const u=new URL(p.media);if(u.protocol==='https:')return u.href;}catch{};return '/api/posts/'+p.id+'/image';}
function image(p,cls=''){const src=mediaSrc(p);return src?`<img class="${cls}" src="${esc(src)}" alt="Картинка к посту" loading="lazy" referrerpolicy="no-referrer">`:`<div class="${cls}">${icon('image')}</div>`;}
function channelLogo(ch,i){return `<div class="channel-logo c${i%4}">${esc(ch.name.replace(/[^\p{L}\p{N}]/gu,'').slice(0,2).toUpperCase())}</div>`;}
function postRow(p){return `<div class="post-row">${image(p,'post-thumb')}<div class="post-row-copy"><div class="channel-name">${esc(p.channel_name)}</div><h3>${esc(p.title)}</h3><p>${p.scheduled_at?fmt(p.scheduled_at):'Готов к твоей проверке'} · #${p.id}</p></div>${badge(p.state)}<button class="icon-btn" data-action="post" data-id="${p.id}" aria-label="Открыть пост">${icon('arrow')}</button></div>`;}
function postCard(p){return `<article class="post-card"><div class="card-media">${image(p)}${badge(p.state)}</div><div class="card-copy"><div class="overline">${esc(p.channel_name)}</div><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p><div class="card-footer"><small>${p.scheduled_at?fmt(p.scheduled_at):fmt(p.created)}</small>${btn('Открыть '+icon('arrow'),'post','small',`data-id="${p.id}"`)}</div></div></article>`;}
function proposalCard(p){
 const ch=S.channels.find(c=>c.id===p.channel_id),kind=ch?.config.mode||'news',initials=p.channel_name.replace(/[^\p{L}\p{N}]/gu,'').slice(0,2).toUpperCase();
 const cover=p.media?image(p):`<span class="cover-orbit"></span><span class="cover-symbol">${icon(kind==='fashion'?'star':kind==='cinema'?'play':'spark')}</span><span class="cover-caption">${kind==='fashion'?'ОБРАЗ':kind==='cinema'?'КИНО':'НОВАЯ ИДЕЯ'}</span><span class="cover-photo-note">Картинка ещё не добавлена</span>`;
 return `<button type="button" class="proposal-card" data-action="post" data-id="${p.id}" data-kind="${esc(kind)}"><span class="proposal-thumbnail">${cover}<span class="cover-status">${badge(p.state)}</span></span><span class="proposal-copy"><span class="proposal-top"><span class="proposal-channel"><span class="channel-mini">${esc(initials)}</span>${esc(p.channel_name)}</span><span class="list-only">${badge(p.state)}</span></span><span class="proposal-title">${esc(p.title)}</span><span class="proposal-excerpt">${esc(p.body)}</span><span class="proposal-bottom"><span>${p.scheduled_at?fmt(p.scheduled_at):fmt(p.created)}</span><span class="proposal-cta">Открыть ${icon('arrow')}</span></span></span></button>`;
}
function postsPage(){
 const statuses={pending:['pending'],draft:['draft'],queued:['approved','publishing','unknown'],all:['pending','draft','approved','publishing','unknown','rejected','sent']};
 const items=S.posts.filter(p=>(statuses[filter]||statuses.pending).includes(p.state)&&(channelFilter==='all'||String(p.channel_id)===channelFilter)&&`${p.title} ${p.channel_name} ${p.body}`.toLowerCase().includes(query.toLowerCase()));
 const tabs=[['pending','На проверке'],['draft','Черновики'],['queued','Запланированы'],['all','Все']];
 return header('Лента','Все каналы. Посты, которым осталось назначить время.',`<div class="flex">${btn(icon(S.paused?'play':'stop')+(S.paused?'На паузе':'Пауза'),S.paused?'resume':'pause')}${navBtn(icon('search')+'Найти посты','search','primary')}</div>`)+pauseNotice()+
 `<section class="proposal-filters"><div class="tabs">${tabs.map(([key,name])=>`<button class="tab ${filter===key?'active':''}" data-action="post-filter" data-value="${key}">${name}<span>${S.posts.filter(p=>(statuses[key]||[]).includes(p.state)).length}</span></button>`).join('')}</div><div class="proposal-search"><div class="view-toggle" aria-label="Вид предложений">${btn(icon('grid'),'proposal-view',proposalView==='gallery'?'active':'',`data-view="gallery" aria-label="Плитка" aria-pressed="${proposalView==='gallery'}"`)}${btn(icon('list'),'proposal-view',proposalView==='list'?'active':'',`data-view="list" aria-label="Список" aria-pressed="${proposalView==='list'}"`)}</div><select id="proposal-channel" aria-label="Фильтр по каналу"><option value="all">Все каналы</option>${S.channels.map(c=>`<option value="${c.id}" ${channelFilter===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><input id="post-query" type="search" placeholder="Найти предложение…" value="${esc(query)}" aria-label="Поиск по постам"></div></section><div class="proposal-summary"><span>Найдено: <strong>${items.length}</strong></span><span>${icon('image')} Предпросмотр по нажатию на карточку</span></div><div id="post-results">${S.channels.map((c,i)=>{const posts=items.filter(p=>p.channel_id===c.id);return posts.length?`<section class="proposal-group"><div class="proposal-group-head">${channelLogo(c,i)}<div><h2>${esc(c.name)}</h2><p>${posts.length} ${plural(posts.length,['материал','материала','материалов'])} · ${c.config.mode==='fashion'?'Одежда и образы':c.config.mode==='cinema'?'Кино':'Контент канала'}</p></div></div><div class="proposal-list ${proposalView}">${posts.map(proposalCard).join('')}</div></section>`:'';}).join('')||empty('Предложений по этому фильтру пока нет','Измени канал, статус или поисковый запрос. Новые материалы появятся после подбора.',navBtn('Начать подбор','search','primary'))}</div><div class="box-note">Последние 300 материалов и вся активная очередь. Посты публикуются только после твоего выбора времени.</div>`;
}
function calendarPage(){
 const queued=S.posts.filter(p=>['approved','publishing','unknown'].includes(p.state)).sort((a,b)=>(a.scheduled_at||a.due)-(b.scheduled_at||b.due));
 const dayKey=ts=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(ts*1000));
 const now=S.now||Date.now()/1000,week=Array.from({length:7},(_,i)=>now+i*86400);
 const items=calendarDay==='all'?queued:queued.filter(p=>dayKey(p.scheduled_at||p.due)===calendarDay);let day='';
 return header('Календарь','Всё на своих местах. Дата и время — московские.',navBtn(icon('plus')+'Добавить пост','posts','primary'))+
 `<section class="calendar-week"><div class="week-heading"><span>Ближайшие 7 дней</span>${btn('Вся очередь','calendar-day',calendarDay==='all'?'active':'',`data-day="all"`)}</div><div class="week-grid">${week.map((ts,i)=>{const key=dayKey(ts),count=queued.filter(p=>dayKey(p.scheduled_at||p.due)===key).length;return `<button class="week-tile ${calendarDay===key?'active':''} ${i===0?'today':''}" data-action="calendar-day" data-day="${key}"><span>${i===0?'Сегодня':new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',weekday:'short'}).format(new Date(ts*1000))}</span><strong>${new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit'}).format(new Date(ts*1000))}</strong><small>${count?count+' '+plural(count,['пост','поста','постов']):'—'}</small></button>`;}).join('')}</div></section>`+pauseNotice()+
 `<section class="panel calendar-panel">${items.map(p=>{const ts=p.scheduled_at||p.due,key=new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'long',weekday:'long'}).format(new Date(ts*1000));let out=key!==day?`<div class="calendar-day">${esc(key)}</div>`:'';day=key;return out+`<div class="calendar-row"><time class="calendar-time">${new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}).format(new Date(ts*1000))}</time><div class="calendar-row-copy"><span class="calendar-channel">${esc(p.channel_name)}</span><h3>${esc(p.title)}</h3></div>${badge(p.state)}${btn('Открыть '+icon('arrow'),'post','small',`data-id="${p.id}"`)}</div>`;}).join('')||empty('Здесь есть место для нового','Открой предложение, выбери дату и время — пост появится в твоём плане.',navBtn('Выбрать пост','posts','primary'))}</section><div class="workspace-footnote">${icon('clock')} Правка текста или фото снимает пост с очереди. После изменения выбери время заново.</div>`;
}
function channelCard(c,i,search=false){const job=S.searches.find(x=>x.channel_id===c.id),working=job&&['new','preparing'].includes(job.state);return `<section class="channel-card"><div class="channel-card-head">${channelLogo(c,i)}<div class="channel-info"><strong>${esc(c.name)}</strong><small>${esc(c.target||'Telegram-канал не подключён')}</small></div>${badge(working?'preparing':c.enabled?'active':'stopped',working?'Идёт поиск':c.enabled?'Активен':'Выключен')}</div><p class="channel-topic">${esc(c.config.topic||'Добавь тему — и студия начнёт подбирать материалы для этого канала.')}</p><div class="channel-time-pills">${c.config.search_times.map(t=>`<span>${icon('clock')}${t}</span>`).join('')}<small>МСК</small></div><dl class="detail-list"><div><dt>Автоподбор</dt><dd>${c.config.auto_search?'Включён':'Выключен'}</dd></div><div><dt>Режим</dt><dd>${{news:'Новости',fashion:'Одежда WB / Ozon',cinema:'Кино'}[c.config.mode]||esc(c.config.mode)}</dd></div><div><dt>Свежесть материалов</dt><dd>За ${c.config.max_age_hours} ч.</dd></div><div><dt>Результат</dt><dd>До двух постов за подбор</dd></div></dl>${search&&job?.error?`<p class="help error">${esc(job.error)}</p>`:''}${sourceStatus(c)}<div class="channel-actions">${btn(icon(working?'stop':'search')+(working?'Остановить поиск':'Найти 2 сейчас'),working?'stop-search':'search','primary small',`data-id="${c.id}"`)}${btn(icon('settings')+'Настроить','channel','small',`data-id="${c.id}"`)}</div></section>`;}
function channelsPage(search=false){return header(search?'Поиск постов':'Мои каналы',search?'Запусти подбор в любое время. Когда два поста готовы, поиск остановится.':'Настройки, источники и расписание для каждого канала.',search?'':btn(icon('plus')+'Добавить канал','add-channel','primary'))+(search?pauseNotice():'')+`<div class="channel-grid">${S.channels.map((c,i)=>channelCard(c,i,search)).join('')}</div>`+(search?'<div class="box-note">Остановка поиска не отменяет уже выполняющийся запрос ИИ. Его результат сохранится в черновиках; новых запросов по остановленной задаче не будет.</div>':'');}
const limitLabels={daily_tokens:'Токенов за день',rolling_tokens:'Токенов за 5 часов',channel_daily_tokens:'На канал за день',daily_requests:'Запросов за день',hourly_requests:'Запросов за час',fashion_steps:'Запросов на подборку одежды (1–2)',fashion_slot_tokens:'Токенов на подборку одежды',fashion_web_calls:'Поисков в запросе одежды (1–8)',fashion_seconds:'Секунд на запрос одежды'};
function limitsPage(){return header('Расход и лимиты','Контролируй расход по журналу приложения. Счётчики сохраняются при обновлениях.')+`<div class="limit-grid">${[['Сегодня',S.usage.tokens,S.limits.daily_tokens],['За последние 5 часов',S.usage.rolling,S.limits.rolling_tokens],['Запросы за день',S.usage.requests,S.limits.daily_requests],['Запросы за час',S.usage.hourly,S.limits.hourly_requests]].map(([name,used,total])=>`<section class="panel"><div class="metric-line"><strong>${name}</strong><span>${num(used)} / ${num(total)}</span></div><div class="progress"><span data-progress="${Math.min(100,used/total*100)}"></span></div><p class="help">${Math.round(used/total*100)}% установленного лимита</p></section>`).join('')}</div><div class="box-note">Это расход, учтённый нашим приложением, а не оставшийся лимит всей подписки ChatGPT. Изменение предела не обнуляет счётчики. «Собрано»: новые запросы не включаются в этот журнал. Найденные вещи сохраняются; один запрос и одно исправление за попытку.</div><section class="panel" style-id="limits"><div class="panel-title"><h2>Настройки бюджета</h2></div><form id="limits-form"><label class="check-label"><input type="checkbox" name="budget_enforced" ${S.budget_enforced?'checked':''}> Останавливать остальные каналы при превышении бюджета</label><p class="help">Без галочки — предупреждения. Для «Собрано» внутренние лимиты и запись новых расходов отключены отдельно. Ограничения поставщика ИИ остаются.</p><div class="form-grid">${Object.entries(limitLabels).filter(([key])=>!S.fashion_unmetered||key!=='fashion_slot_tokens').map(([key,name])=>`<div>${field(name,key,S.limits[key],'number')}</div>`).join('')}</div><div class="form-actions">${btn('Сохранить лимиты','submit-limits','primary','type="submit"')}</div></form></section>`;}
function campaignsPage(){return header('Рекламные рассылки','Один пост для выбранных групп. Отправка по очереди с паузами.',btn(icon('plus')+'Новая рассылка','new-campaign','primary'))+`<section class="manager-banner"><div class="banner-symbol">${icon('send')}</div><div><span class="panel-eyebrow">СПОКОЙНОЕ ПРОДВИЖЕНИЕ</span><h2>Каждая отправка — под контролем.</h2><p>Пост, группы, интервалы. Ты запускаешь — студия следит за очередью.</p></div><div class="banner-status">${badge(S.account.connected?'active':'draft',S.account.connected?'Аккаунт подключён':'Начни с черновика')}</div></section>`+stats([['Кампании',num(S.campaigns.length),'черновики и запущенные','send'],['Активные',num(S.campaigns.filter(c=>c.state==='active').length),'одна рассылка на аккаунт','play'],['Группы',num(new Set(S.campaigns.flatMap(c=>c.targets)).size),'добавлены вручную','users'],['Аккаунт',S.account.connected?'Подключён':'Не подключён',S.account.connected?esc(S.account.name||'Telegram'):'можно готовить черновики','account']])+(!S.account.connected?`<div class="notice"><div class="grow">Подключение аккаунта понадобится для отправки и поиска партнёров. Кампании уже можно создавать и редактировать.</div>${navBtn('Как подключить','account','small')}</div>`:'')+`<div class="channel-grid">${S.campaigns.map(c=>`<section class="channel-card"><div class="panel-title"><h2>${esc(c.name)}</h2>${badge(c.state)}</div><div class="campaign-text">${esc(c.text)}</div><div class="send-sequence">${c.targets.slice(0,3).map((t,i)=>`<div><span>${i+1}</span><small>${i?'+'+c.gap_minutes*i+' мин.':'Старт'}</small><strong>${esc(t)}</strong></div>`).join('')}${c.targets.length>3?`<div class="sequence-more">+${c.targets.length-3}</div>`:''}</div><dl class="detail-list"><div><dt>Групп</dt><dd>${c.targets.length}</dd></div><div><dt>Между группами</dt><dd>${c.gap_minutes} мин.</dd></div><div><dt>Повтор круга</dt><dd>От ${Math.max(c.cycle_minutes,c.targets.length*c.gap_minutes)} мин.</dd></div><div><dt>Следующая отправка</dt><dd>${c.state==='active'?fmt(c.next_at):'После запуска'}</dd></div></dl>${c.reason?`<p class="help">${esc(c.reason)}</p>`:''}${sourceStatus(c)}<div class="channel-actions">${btn(icon(['active','checking'].includes(c.state)?'stop':'play')+(['active','checking'].includes(c.state)?'Стоп':'Старт'),['active','checking'].includes(c.state)?'campaign-stop':'campaign-start','primary small',`data-id="${esc(c.id)}"`)}${btn('Изменить','campaign','small',`data-id="${esc(c.id)}"`)}${btn('Журнал','campaign-log','small',`data-id="${esc(c.id)}"`)}</div></section>`).join('')||empty('Первая рассылка начинается с поста','Добавь текст и группы, в которых разрешена твоя реклама. По умолчанию: 2 минуты между группами, 30 минут между кругами.',btn('Создать рассылку','new-campaign','primary'))}</div><div class="box-note">Кнопка «Стоп» отменяет последующие отправки. Уже начатая отправка может завершиться. При ограничениях Telegram рассылка останавливается; интервалы не гарантируют отсутствие блокировок.</div>`;}
function partnersPage(){const f=S.partner_filter,j=S.partner_search;return header('Партнёры для сотрудничества','Находим похожие каналы. Решение о сотрудничестве остаётся за тобой.',btn(icon('search')+'Найти до 10 каналов','partner-search','primary'))+`<div class="columns"><section class="panel"><div class="panel-title"><h2>Найденные каналы</h2>${j.state?badge(j.state):''}</div>${j.error?`<p class="error">${esc(j.error)}</p>`:''}${S.partners.filter(p=>!p.hidden).map(p=>`<div class="post-row"><div class="channel-logo">${esc(p.title.slice(0,2).toUpperCase())}</div><div class="post-row-copy"><h3><a href="${safeLink(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ↗</a></h3><p>${p.subscribers===null?'Подписчики неизвестны':num(p.subscribers)+' подписчиков'} · ${esc(p.origin)}</p><p>${esc(p.about.slice(0,120))}</p></div><button class="icon-btn" data-action="partner-favorite" data-peer="${esc(p.peer)}" aria-label="В избранное">${p.favorite?'★':'☆'}</button><button class="icon-btn" data-action="partner-hide" data-peer="${esc(p.peer)}" aria-label="Скрыть">${icon('close')}</button></div>`).join('')||empty('Найдём подходящие каналы','Укажи тему поиска справа. Для поиска нужен подключённый Telegram-аккаунт.')}</section><div><section class="panel"><div class="panel-title"><h2>Параметры поиска</h2></div><form id="partner-form">${area('Темы поиска','queries',(f.queries||[]).join('\n'),'От одной до трёх тем, каждая с новой строки.')}${field('Подписчиков от','min',f.min||0,'number')}${field('Подписчиков до','max',f.max||0,'number','0 — без верхней границы.')}<div class="form-actions"><button class="btn primary" type="submit">Сохранить</button></div></form></section><div class="box-note">Только поиск и ссылки. Сообщения, подписки и приглашения автоматически не отправляются.</div>${['queued','running'].includes(j.state)?btn('Остановить поиск','partner-stop','danger'):''}</div></div>`;}
function accountPage(){return header('Аккаунт отправителя','Отдельное подключение для рассылок по группам и поиска партнёров.')+`<div class="settings-tiles"><section class="panel"><div class="panel-title"><h2>Telegram-аккаунт</h2>${badge(S.account.connected?'active':'stopped',S.account.connected?'Подключён':'Не подключён')}</div><p>${esc(S.account.note||'Подключение пока не настроено.')}</p>${S.account.name?`<p>Аккаунт: <strong>${esc(S.account.name)}</strong></p>`:''}${S.cooldown>S.now?`<p class="error">Пауза Telegram до ${fmt(S.cooldown)}</p>`:''}${btn('Проверить подключение','check-account')}</section><section class="panel"><h3>Как подключить</h3><p>Добавь в ENV хостинга <code>MANAGER_ENABLED=1</code>, <code>MANAGER_API_ID</code> и <code>MANAGER_API_HASH</code>. Получи их для своего приложения Telegram.</p><p>Останови процесс и выполни в интерактивном терминале сервера:</p><code class="codeblock">python main.py manager-login</code><p>Введи телефон, код и пароль только в терминале, затем запусти приложение. Подробности — в инструкции из архива.</p></section></div><div class="box-note">Без аккаунта доступны черновики рассылок. API и сессия Telegram хранятся на сервере; вводить их на сайте не нужно.</div>`;}
