function settingsPage(){return header('Настройки студии','Подключения, модель и состояние приложения.','', 'ОБЩЕЕ / НАСТРОЙКИ')+`<div class="settings-tiles"><section class="panel"><div class="panel-title"><h2>Подключение ИИ</h2>${badge(S.ai_connected?'active':'stopped',S.ai_connected?'Вход сохранён':'Нужен вход')}</div><p>Модель: <strong>${esc(S.model||'не выбрана')}</strong></p><form id="model-form"><label for="model">Модель</label><select id="model" name="model">${[...new Set([S.model,...S.models.map(m=>m.slug)].filter(Boolean))].map(m=>`<option value="${esc(m)}" ${m===S.model?'selected':''}>${esc(m)}</option>`).join('')||'<option value="">Сначала выполни вход</option>'}</select><div class="form-actions"><button class="btn primary" type="submit">Сохранить модель</button></div></form><p>Текущая модель сохраняется при обновлении. Если каталога нет, на сервере: <code>python -m smm model</code>. Вход ChatGPT: <code>python -m smm auth login</code> в интерактивном терминале.</p></section><section class="panel"><h3>Приложение на телефоне</h3><p>Установи студию на главный экран: она откроется отдельным окном. Для поиска, публикаций и изменений нужно подключение к интернету.</p>${btn(icon('plus')+'Установить приложение','install')}<hr class="thin-separator"><h3>Система</h3><p>Версия <strong>${esc(S.version)}</strong><br>Часовой пояс: Москва (UTC+3)<br>Интерфейс и бот используют одну базу.<br>Сессия сайта действует 24 часа.</p><div class="flex">${btn(icon('logout')+'Выйти','logout')}${btn('Остановить всё','stop-all','danger')}</div></section></div><section class="panel"><div class="panel-title"><h2>Последние действия в веб-панели</h2></div><div class="table-scroll"><table><thead><tr><th>Когда</th><th>Telegram ID</th><th>Действие</th></tr></thead><tbody>${S.audit.map(a=>`<tr><td>${fmt(a.created)}</td><td>${a.actor}</td><td>${esc(a.action)}</td></tr>`).join('')||'<tr><td colspan="3">Здесь появится история изменений.</td></tr>'}</tbody></table></div></section>`;}
function render(){if(!S)return;const r=route();if(smmRoutes.includes(r))section='smm';if(mgrRoutes.includes(r))section='manager';try{localStorage.setItem('studio-section',section);}catch{}$('#section-smm').classList.toggle('active',section==='smm');$('#section-manager').classList.toggle('active',section==='manager');$('#mobile-smm').classList.toggle('active',section==='smm');$('#mobile-manager').classList.toggle('active',section==='manager');$('#side-label').textContent=section==='smm'?'КОНТЕНТ И ПУБЛИКАЦИИ':'РЕКЛАМА И СОТРУДНИЧЕСТВО';const nav=section==='smm'?[['posts','posts','Лента'],['calendar','calendar','Календарь'],['channels','channels','Каналы'],['more','menu','Ещё']]:[['campaigns','send','Рассылки'],['partners','users','Партнёры'],['account','account','Аккаунт отправителя'],['log','log','Журнал отправок']];$('#mobile-bottom').innerHTML=(section==='smm'?[['posts','posts','Лента'],['calendar','calendar','Календарь'],['channels','channels','Каналы'],['more','menu','Ещё']]:[['campaigns','send','Рассылки'],['partners','users','Партнёры'],['account','account','Аккаунт'],['log','log','Журнал']]).map(([key,i,name])=>`<button class="${r===key?'active':''}" data-nav="${key}">${icon(i)}<span>${name}</span></button>`).join('');$('#navigation').innerHTML=nav.map(([key,i,name])=>`<button class="nav-item ${r===key?'active':''}" data-nav="${key}">${icon(i)}${name}${key==='posts'&&S.posts.some(p=>p.state==='pending')?`<span class="count">${S.posts.filter(p=>p.state==='pending').length}</span>`:''}</button>`).join('');$$('.sidebar-bottom [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===r));const unread=S.notice_unread||0;$('#notice-count').textContent=unread>99?'99+':unread;$('#notice-count').hidden=!unread;$('#notification-button').setAttribute('aria-label','Уведомления'+(unread?' · непрочитанных: '+unread:''));$('#breadcrumb').textContent=routes[r];$('#avatar').textContent=S.actor===S.owner?'В':'С';document.title=routes[r]+' · Студия';document.body.dataset.section=section;const views={notifications:notificationsPage,more:morePage,posts:postsPage,calendar:calendarPage,channels:()=>channelsPage(),search:()=>channelsPage(true),limits:limitsPage,campaigns:campaignsPage,partners:partnersPage,account:accountPage,log:logPage,team:teamPage,settings:settingsPage};$('#content').innerHTML=views[r]();$$('[data-progress]').forEach(e=>e.style.width=e.dataset.progress+'%');hydrateIcons();applyTheme();$('#content').classList.toggle('motion-enter',lastRoute!==r);if(lastRoute!==r){window.scrollTo(0,0);lastRoute=r;}}
function safeLink(value){try{const u=new URL(value);if(['http:','https:'].includes(u.protocol))return esc(u.href);}catch{}return '#';}
function safeTelegramHtml(value){
 const source=new DOMParser().parseFromString(value,'text/html'),target=document.createElement('div');
 function copy(node,parent){
  if(node.nodeType===Node.TEXT_NODE){parent.append(document.createTextNode(node.textContent));return;}
  if(node.nodeType!==Node.ELEMENT_NODE)return;
  let next=parent;
  if(['B','STRONG'].includes(node.tagName)){next=document.createElement('b');parent.append(next);}
  else if(node.tagName==='A'){try{const url=new URL(node.getAttribute('href'));if(['http:','https:'].includes(url.protocol)){next=document.createElement('a');next.href=url.href;next.target='_blank';next.rel='noopener noreferrer';parent.append(next);}}catch{}}
  for(const child of node.childNodes)copy(child,next);
 }
 for(const node of source.body.childNodes)copy(node,target);
 return target.innerHTML;
}
function postModal(id){
 const p=S.posts.find(x=>x.id===Number(id));if(!p)return;
 const editable=['pending','draft','approved'].includes(p.state),ch=S.channels.find(c=>c.id===p.channel_id),clock=p.scheduled_at?new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}).format(new Date(p.scheduled_at*1000)):'Черновик';
 modal('Так будет выглядеть пост',`<div class="post-preview-layout"><div><div class="telegram-preview"><div class="tg-channel-bar"><span aria-hidden="true">${icon('back')}</span>${channelLogo(ch||{name:p.channel_name},p.channel_id)}<div><strong>${esc(p.channel_name)}</strong><small>предпросмотр публикации</small></div><span class="tg-dots" aria-hidden="true">⋮</span></div><div class="tg-chat"><div class="tg-date">Предпросмотр · #${p.id}</div><article class="tg-bubble">${p.media?image(p,'tg-image'):''}<div class="tg-post-text">${safeTelegramHtml(p.preview_html||'<b>'+esc(p.title)+'</b>\n\n'+esc(p.body))}</div><div class="tg-message-footer">${esc(clock)}${p.scheduled_at?' · МСК':''}</div></article></div></div><p class="preview-note">Внешний вид приближен к Telegram. Шрифт и переносы могут отличаться на устройствах.</p></div><aside class="post-side"><div class="post-side-label">${esc(p.channel_name)}</div>${badge(p.state)}${p.meta.unverified?'<div class="notice red">Сначала проверь вещи, цены и наличие по ссылкам.</div>':''}${p.scheduled_at?`<div class="box-note">Выйдет <strong>${fmt(p.scheduled_at)} МСК</strong></div>`:'<p class="help">Выбери время, когда пост увидят подписчики. До этого он останется в предложениях.</p>'}${p.publication_error?`<p class="error">${esc(p.publication_error)}</p>`:''}<div class="post-side-actions">${editable?`${btn(icon('calendar')+(p.scheduled_at?'Изменить время':'Выбрать время'),'schedule','primary',`data-id="${p.id}"`)}${btn(icon('posts')+'Текст и картинка','edit-post','',`data-id="${p.id}"`)}`:''}${p.state==='unknown'?`${btn('Проверил: пост вышел','resolve-post-sent','',`data-id="${p.id}"`)}${btn('Проверил: поста нет','resolve-post-missing','',`data-id="${p.id}"`)}`:''}</div>${editable?`<div class="post-secondary-actions">${p.scheduled_at?btn('Снять с очереди','unschedule','ghost',`data-id="${p.id}"`):''}${p.meta.mode==='fashion'&&p.meta.unverified?btn('Я проверил товары и цены','verify-post','ghost',`data-id="${p.id}"`):''}${btn('В черновики','draft-post','ghost',`data-id="${p.id}"`)}${btn('Отклонить','reject-post','ghost',`data-id="${p.id}"`)}</div>`:''}</aside></div><details class="source-details"><summary>Источники и товары для проверки</summary>${postLinks(p)||'<p class="help">У этого материала нет дополнительных ссылок.</p>'}</details>`,'СММ / ПРЕДПРОСМОТР ПОСТА');
 $('.modal').classList.add('preview-modal');focusModal();
}
function postLinks(p){
 const products=Array.isArray(p.meta.products)?p.meta.products:[];
 const money=n=>Number.isFinite(Number(n))?num(n)+' ₽':'Цена не подтверждена';
 let out=products.length?`<div class="post-meta-links"><strong>Состав образа</strong>${products.map(x=>`<div class="product-row"><a href="${safeLink(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.name||x.title||'Карточка товара')} ↗</a><span>${money(x.price)}</span></div>`).join('')}${p.meta.total?`<p><strong>Весь образ: ${money(p.meta.total)}</strong></p>`:''}${p.meta.budget?`<p class="help">Бюджет: ${money(p.meta.budget)}</p>`:''}</div>`:'';
 const sources=Array.isArray(p.meta.sources)?p.meta.sources:[];
 if(sources.length)out+=`<div class="post-meta-links"><strong>Источники</strong><br>${sources.map(x=>{const url=typeof x==='string'?x:x.url,name=typeof x==='string'?x:x.title||x.name||url;return `<a href="${safeLink(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>`;}).join('<br>')}</div>`;
 return out;
}
function scheduleModal(id){const p=S.posts.find(p=>p.id===+id);if(!p)return;if(p.batch_kind!=='batch'){toast('Этот пост из старой очереди. Управляй им через Telegram; новые предложения поддерживают выбор времени.',true);return;}const value=p.scheduled_at?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(p.scheduled_at*1000)).replace(' ','T'):'';modal('Когда опубликовать?',`<p class="help">${esc(p.title)} · ${esc(p.channel_name)}</p><form id="schedule-form" data-id="${id}">${field('Дата и время по Москве','time',value,'datetime-local','В пределах 30 дней. Время не переводится в часовой пояс твоего устройства.')}<div class="flex">${btn('Через 30 минут','quick-schedule','small',`data-id="${id}" data-time="через 30 мин"`)}${btn('Завтра в 12:00','quick-schedule','small',`data-id="${id}" data-time="завтра 12:00"`)}</div><p class="error" id="form-error"></p><div class="form-actions">${btn('Назад к посту','post','',`data-id="${id}"`)}<button type="submit" class="btn primary">Запланировать</button></div></form>`,'СММ / ПЛАНИРОВАНИЕ');focusModal();}
function editPost(id){const p=S.posts.find(p=>p.id===+id);modal('Редактор поста',`<div class="notice">После изменения текста или картинки время публикации нужно выбрать заново. Правка не вызывает ИИ.</div><form id="post-form" data-id="${id}">${area('Основной текст (до 650 знаков)','body',p.body)}${field('Ссылка на фото (HTTPS) — необязательно','media',/^https?:/.test(p.media)?p.media:'','url','Оставь поле пустым, чтобы сохранить прикреплённую картинку.')}<p class="error" id="form-error"></p><div class="form-actions">${btn('Назад','post','',`data-id="${id}"`)}<button class="btn primary" type="submit">Сохранить текст / ссылку</button></div></form><hr class="thin-separator"><form id="image-form" data-id="${id}"><label for="upload-image">Или загрузи картинку с устройства</label><input id="upload-image" name="image" type="file" accept="image/jpeg,image/png,image/webp" required><p class="help">JPEG, PNG или WebP, до 10 МБ. Сначала сохрани текст, затем загружай фото.</p><button class="btn" type="submit">Загрузить фото</button></form>`,'СММ / РЕДАКТОР');focusModal();}
function channelModal(id){const c=S.channels.find(c=>c.id===+id),v=c.config;modal('Настройки канала',`<form id="channel-form" data-id="${id}"><div class="form-grid"><div class="full">${field('Название в студии','name',c.name)}</div><div><label for="channel-mode">Режим</label><select name="mode" id="channel-mode">${[['news','Новости'],['fashion','Одежда WB / Ozon'],['cinema','Кино']].map(([k,n])=>`<option value="${k}" ${v.mode===k?'selected':''}>${n}</option>`).join('')}</select></div><div>${field('Возраст материалов, часы','max_age_hours',v.max_age_hours,'number')}</div><div class="full">${area('Тематика: что подбирать','topic',v.topic)}${area('Стиль текста','style',v.style)}<label for="source-preset">Добавить набор источников</label><div class="flex"><select id="source-preset" aria-label="Набор источников"><option value="ai">ИИ и нейросети</option><option value="cinema">Кино</option><option value="finance">Финансы</option><option value="football">Футбол</option></select>${btn('Добавить в список','source-preset')}</div>${area('Источники RSS / JSON Feed','sources',v.sources.join('\n'),'До 30 лент, по одной на строку. Набор дополняет список. Для применения нажми «Сохранить настройки».')}</div><div>${area('Ключевые слова','include',v.include.join('\n'))}</div><div>${area('Стоп-слова и запреты','exclude',v.exclude.join('\n'))}</div><div class="full">${field('Три времени автоподбора, МСК','search_times',v.search_times.join(' '),'text','Например: 09:00 15:00 21:00. Это время поиска, время публикации выбираешь отдельно.')}<label class="check-label"><input type="checkbox" name="auto_search" ${v.auto_search?'checked':''}> Автоподбор три раза в день</label><label class="check-label"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}> Канал включён</label><label class="check-label"><input type="checkbox" name="require_photo" ${v.require_photo?'checked':''}> Картинка обязательна</label><label class="check-label"><input type="checkbox" name="web_search" ${v.web_search?'checked':''}> Веб-поиск товаров (для одежды)</label>${area('Бюджеты образов, JSON','budgets',JSON.stringify(v.budgets,null,2),'Пример: {"09:00": 10000, "15:00": 10000, "21:00": 20000}')}</div></div><p class="error" id="form-error"></p><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Закрыть</button><button class="btn primary" type="submit">Сохранить настройки</button></div></form><hr class="thin-separator"><form id="connect-form" data-id="${id}">${field('Подключить Telegram-канал','target',c.target||'','text','Добавь бота администратором с правом публикации. Укажи @имя_канала или ID -100…')}<button class="btn" type="submit">Проверить права и подключить</button></form>`,'СММ / КАНАЛ');focusModal();}
function newCampaign(){modal('Новая рассылка',`<form id="campaign-new-form">${field('Название','name')}${area('Один общий пост для всех групп','text','','До 3500 знаков. Без HTML-разметки.')}${area('Группы','targets','','По одной @группе или https://t.me/группа на строку. Добавляй группы, где разрешены твои сообщения.')}<div class="box-note">По умолчанию — 2 минуты между группами и 30 минут между началами кругов. После создания рассылка останется черновиком.</div><p class="error" id="form-error"></p><div class="form-actions"><button class="btn primary" type="submit">Создать черновик</button></div></form>`,'МЕНЕДЖЕР / РАССЫЛКИ');focusModal();}
function campaignModal(id){const c=S.campaigns.find(c=>c.id===id);if(!c)return;modal(c.name,`<form id="campaign-text-form" data-id="${esc(id)}">${area('Общий текст рассылки','text',c.text,'Быстрая правка: новый текст применяется к ещё не начатым отправкам.')}<div class="form-actions"><button class="btn primary" type="submit">Сохранить текст</button></div></form><hr class="thin-separator"><p class="help">Изменение списка групп или интервалов остановит кампанию. Затем проверь настройки и снова нажми «Старт».</p><form id="campaign-field-form" data-id="${esc(id)}"><label for="campaign-field">Что изменить</label><select id="campaign-field" name="field"><option value="targets">Группы</option><option value="gap_minutes">Пауза между группами, 2–60 мин.</option><option value="cycle_minutes">Период круга, 30–1440 мин.</option><option value="daily_limit">Отправок в день, 1–1000</option></select>${area('Новое значение','value',c.targets.join('\n'))}<p class="error" id="form-error"></p><div class="form-actions">${btn('Удалить рассылку','campaign-delete','danger',`data-id="${esc(id)}"`)}<button class="btn" type="submit">Применить</button></div></form>`,'МЕНЕДЖЕР / НАСТРОЙКИ');focusModal();}
function confirmAction(title,text,yes){modal(title,`<p class="preview-body">${esc(text)}</p><div class="form-actions">${btn('Отмена','close-modal')}<button id="confirm-yes" class="btn primary">Подтвердить</button></div>`);$('#confirm-yes').addEventListener('click',async()=>{const b=$('#confirm-yes');b.disabled=true;try{await yes();closeModal();}catch(e){toast(e.message,true);b.disabled=false;}});focusModal();}
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id;
 if(a==='source-preset'){const key=$('#source-preset').value,field=$('#f-sources'),sources=[...new Set([...field.value.split('\n').map(s=>s.trim()).filter(Boolean),...(S.source_presets?.[key]||[])])];if(sources.length>30)throw new Error('Сначала освободи место: максимум 30 лент.');field.value=sources.join('\n');toast('Источники добавлены в форму. Сохрани настройки канала.');return;}
 if(a==='read-notices'){await mutate('/api/notices/read',{until:S.notices?.[0]?.id||0},'Уведомления прочитаны');return;}
 if(a==='theme'){setTheme(document.documentElement.dataset.theme==='light'?'dark':'light');return;}if(a==='command'){commandPalette();return;}if(a==='proposal-view'){proposalView=el.dataset.view;try{localStorage.setItem('studio-proposal-view',proposalView);}catch{};render();return;}if(a==='calendar-day'){calendarDay=el.dataset.day;render();return;}if(a==='close-modal'){closeModal();return;} if(a==='menu'){$('#sidebar').classList.toggle('open');$('#scrim').hidden=!$('#sidebar').classList.contains('open');syncSidebar();return;}if(a==='back'){if(history.length>1)history.back();else go(section==='smm'?'posts':'campaigns');return;}
 if(a==='section-smm'||a==='section-manager'){switchSection(a.slice(8));return;}if(a==='refresh'){await load();return;}
 if(a==='post-filter'){filter=el.dataset.value;render();return;}if(a==='post'){postModal(id);return;}if(a==='schedule'){scheduleModal(id);return;}if(a==='edit-post'){editPost(id);return;}if(a==='channel'){channelModal(id);return;}if(a==='new-campaign'){newCampaign();return;}if(a==='campaign'){campaignModal(id);return;}if(a==='campaign-log'){go('log');return;}
 if(a==='add-channel'){modal('Добавить канал',`<form id="add-channel-form">${field('Название','name')}<p class="help">Канал будет создан выключенным. Затем подключи Telegram-канал и настрой тему.</p><p id="form-error" class="error"></p><div class="form-actions"><button class="btn primary" type="submit">Добавить</button></div></form>`,'СММ / НОВЫЙ КАНАЛ');focusModal();return;}
 if(a==='invite'){modal('Пригласить совладельца',`<form id="invite-form">${field('Telegram ID будущего совладельца','id','','text','Участник получит полный доступ к каналам, постам, рассылкам и настройкам.')}<p class="error" id="form-error"></p><div class="form-actions"><button type="submit" class="btn primary">Создать приглашение</button></div></form>`,'КОМАНДА / ДОСТУП');focusModal();return;}
 if(a==='pause'||a==='stop-all'||a==='resume'){confirmAction(a==='resume'?'Продолжить работу?':a==='pause'?'Поставить СММ на паузу?':'Остановить всё?',a==='resume'?'Поиск возобновится, одобренные посты будут выходить по расписанию. Счётчики не обнуляются.':a==='pause'?'Новые запросы ИИ и публикации остановятся. Уже начатая операция может завершиться.':'Остановятся СММ, рассылки и поиск партнёров. Уже начатая отправка может завершиться.',()=>mutate('/api/control',{action:a==='stop-all'?'stop_all':a},a==='resume'?'СММ продолжает работу':'Остановлено'));return;}
 if(a==='search'||a==='stop-search'){await mutate('/api/channels/'+id,{action:a==='search'?'search':'stop_search'},a==='search'?'Поиск поставлен в очередь. До двух постов за подбор.':'Поиск остановлен. Выполняющийся запрос может завершиться.');return;}
 if(a==='quick-schedule'){await mutate('/api/posts/'+id,{action:'schedule',time:el.dataset.time},'Время публикации сохранено');closeModal();return;}
 if(a==='unschedule'||a==='draft-post'||a==='reject-post'||a==='verify-post'){if(a==='verify-post'){confirmAction('Подтвердить проверку товаров?','Подтверди, что ты открыл ссылки и проверил вещи, цены и наличие. После этого можно выбрать время публикации.',()=>mutate('/api/posts/'+id,{action:'verified'},'Проверка отмечена'));return;}await mutate('/api/posts/'+id,{action:{unschedule:'unschedule','draft-post':'draft','reject-post':'reject'}[a]});closeModal();return;}
 if(a==='resolve-post-sent'||a==='resolve-post-missing'){confirmAction('Сохранить результат проверки?','Проверь канал вручную. Отмечаем результат без автоматического повтора отправки.',()=>mutate('/api/posts/'+id,{action:'resolve',sent:a==='resolve-post-sent'}));return;}
 if(a==='campaign-start'||a==='campaign-stop'||a==='campaign-delete'){const action=a.split('-')[1];if(action==='start'||action==='delete'){confirmAction(action==='start'?'Запустить рассылку?':'Удалить рассылку?',action==='start'?'Сообщения начнут отправляться в указанные группы после проверки прав. Проверь текст, список групп и интервалы.':'Кампания будет удалена. История отправок останется в журнале.',()=>mutate('/api/campaigns/'+id,{action},action==='start'?'Кампания запущена: проверяем группы.':'Кампания удалена'));}else await mutate('/api/campaigns/'+id,{action},'Рассылка остановлена');return;}
 if(a==='manager-stop'){await mutate('/api/manager',{action:'stop'},'Рассылки остановлены');return;}if(a==='check-account'){await mutate('/api/manager',{action:'check_account'},'Проверка подключения поставлена в очередь');return;}
 if(a==='delivery-sent'||a==='delivery-missing'){confirmAction('Подтвердить результат отправки?','Сначала проверь соответствующую группу вручную. Повторной отправки сейчас не будет.',()=>mutate('/api/manager',{action:'resolve',id:+id,sent:a==='delivery-sent'}));return;}
 if(a.startsWith('partner-')){const action={ 'partner-search':'search','partner-stop':'stop','partner-favorite':'favorite','partner-hide':'hide'}[a];if(action)await mutate('/api/partners',{action,peer:el.dataset.peer},action==='search'?'Поиск партнёров поставлен в очередь':'Сохранено');return;}
 if(a==='remove-member'){confirmAction('Отозвать доступ?',`Участник ${id} потеряет доступ к Telegram-боту и сайту. Его сессии будут закрыты.`,()=>mutate('/api/team',{action:'remove',id}));return;}
 if(a==='install'){await installApp();return;}if(a==='logout'){await api('/api/logout',{});showLogin();return;}
}
document.addEventListener('click',async event=>{const nav=event.target.closest('[data-nav]');if(nav){event.preventDefault();go(nav.dataset.nav);return;}const el=event.target.closest('[data-action]');if(!el)return;if(el.type==='submit'&&el.closest('form'))return;event.preventDefault();if(busy)return;busy=true;el.disabled=true;try{await handleAction(el);}catch(e){toast(e.message,true);}finally{el.disabled=false;busy=false;}});
document.addEventListener('submit',async event=>{const form=event.target;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit?.disabled)return;if(submit)submit.disabled=true;const d=Object.fromEntries(new FormData(form)),id=form.dataset.id;try{
 if(form.id==='login-form'){await api('/api/login',d);$('#login-code').value='';await load();return;}
 if(form.id==='schedule-form'){await mutate('/api/posts/'+id,{action:'schedule',time:d.time},'Публикация запланирована');closeModal();}
 if(form.id==='post-form'){const p=S.posts.find(p=>p.id===+id);await mutate('/api/posts/'+id,{action:'edit',body:d.body,media:d.media||p.media},'Пост сохранён. Выбери время заново.');postModal(id);}
 if(form.id==='image-form'){await mutate('/api/posts/'+id+'/image',new FormData(form),'Картинка прикреплена. Выбери время заново.');postModal(id);}
 if(form.id==='channel-form'){let budgets;try{budgets=JSON.parse(d.budgets||'{}');}catch{throw new Error('В бюджетах нужен корректный JSON: {"09:00": 10000}');}await mutate('/api/channels/'+id,{action:'save',name:d.name,enabled:!!d.enabled,config:{mode:d.mode,topic:d.topic,style:d.style,max_age_hours:+d.max_age_hours,search_times:d.search_times,sources:d.sources.split('\n'),include:d.include.split('\n'),exclude:d.exclude.split('\n'),auto_search:!!d.auto_search,require_photo:!!d.require_photo,web_search:!!d.web_search,budgets}});closeModal();}
 if(form.id==='connect-form'){await mutate('/api/channels/'+id,{action:'connect',target:d.target},'Канал подключён. Его можно включить.');channelModal(id);}
 if(form.id==='add-channel-form'){await mutate('/api/channels',{name:d.name},'Канал создан');closeModal();}
 if(form.id==='limits-form'){await mutate('/api/limits',{...Object.fromEntries(Object.entries(d).filter(([k])=>k!=='budget_enforced').map(([k,v])=>[k,+v])),budget_enforced:!!d.budget_enforced},'Лимиты сохранены. Счётчики не изменены.');}
 if(form.id==='model-form'){await mutate('/api/model',d,'Модель сохранена');}
 if(form.id==='campaign-new-form'){await mutate('/api/campaigns',d,'Черновик рассылки создан');closeModal();}
 if(form.id==='campaign-text-form'){await mutate('/api/campaigns/'+id,{action:'edit',field:'text',value:d.text},'Текст обновлён для следующих отправок');closeModal();}
 if(form.id==='campaign-field-form'){await mutate('/api/campaigns/'+id,{action:'edit',field:d.field,value:d.value},'Настройки обновлены. Кампания остановлена.');closeModal();}
 if(form.id==='partner-form'){await mutate('/api/partners',{action:'filters',...d},'Фильтры партнёров сохранены');}
 if(form.id==='invite-form'){const r=await api('/api/team',{action:'invite',id:d.id});modal('Приглашение готово',`<p class="preview-body">Передай участнику ${esc(d.id)} эту команду. Он должен отправить её нашему Telegram-боту в течение 30 минут:</p><code class="codeblock">${esc(r.command)}</code><p class="help">После принятия приглашения он сможет получить код входа командой /web. Новое приглашение заменяет предыдущее неиспользованное.</p>`,'КОМАНДА / ПРИГЛАШЕНИЕ');focusModal();}
 }catch(e){const error=form.id==='login-form'?$('#login-error'):$('#form-error',form)||$('#form-error');if(error)error.textContent=e.message;else toast(e.message,true);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='command-query'){renderCommand(event.target.value);return;}if(event.target.id==='post-query'){query=event.target.value;const start=event.target.selectionStart;render();const q=$('#post-query');q?.focus();try{q?.setSelectionRange(start,start);}catch{}}});
document.addEventListener('change',event=>{if(event.target.id==='proposal-channel'){channelFilter=event.target.value;render();return;}if(event.target.id==='campaign-field'){const f=$('#campaign-field-form'),c=S.campaigns.find(c=>c.id===f.dataset.id),key=event.target.value;f.elements.value.value=key==='targets'?c.targets.join('\n'):c[key];}});
document.addEventListener('keydown',event=>{if($('#modal').hidden)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const items=$$('button:not([disabled]),a,input,select,textarea',$('#modal')).filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});$('#scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#scrim').hidden=true;syncSidebar();});
