function applyTheme(){
 const light=document.documentElement.dataset.theme==='light';
 const button=$('[data-action="theme"]');if(button){button.dataset.icon=light?'moon':'sun';button.setAttribute('aria-label',light?'Включить тёмную тему':'Включить светлую тему');button.innerHTML=icon(light?'moon':'sun');}
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',light?'#f5f6f8':'#101216');
}
function setTheme(theme){document.documentElement.dataset.theme=theme;try{localStorage.setItem('studio-theme',theme);}catch{}applyTheme();}
function commandPalette(){
 modal('Куда переходим?',`<div class="command-search">${icon('search')}<input id="command-query" type="search" placeholder="Экран, канал или пост…" autocomplete="off" aria-label="Быстрый переход"></div><div id="command-results"></div><p class="help command-hint">Ctrl / ⌘ + K — открыть · Esc — закрыть</p>`,'БЫСТРЫЙ ПЕРЕХОД');renderCommand('');$('#command-query').focus();
}
function renderCommand(query){
 const q=query.trim().toLowerCase(),pages=Object.entries(routes).filter(([k,v])=>!q||v.toLowerCase().includes(q)).slice(0,q?6:5);
 let html=pages.map(([key,name])=>`<button class="command-row" data-nav="${key}"><span>${icon(key==='home'?'home':key==='calendar'?'calendar':key==='channels'?'channels':'arrow')}</span><span><strong>${esc(name)}</strong><small>Раздел студии</small></span>${icon('chevron')}</button>`).join('');
 if(q){html+=S.channels.filter(c=>c.name.toLowerCase().includes(q)).slice(0,4).map(c=>`<button class="command-row" data-action="channel" data-id="${c.id}"><span>${icon('channels')}</span><span><strong>${esc(c.name)}</strong><small>Настройки канала</small></span>${icon('chevron')}</button>`).join('');html+=S.posts.filter(p=>p.title.toLowerCase().includes(q)).slice(0,4).map(p=>`<button class="command-row" data-action="post" data-id="${p.id}"><span>${icon('posts')}</span><span><strong>${esc(p.title)}</strong><small>${esc(p.channel_name)}</small></span>${icon('chevron')}</button>`).join('');}
 $('#command-results').innerHTML=html||'<p class="help">Ничего не нашлось. Попробуй другое название.</p>';
}
document.addEventListener('keydown',event=>{if(S&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();commandPalette();}});
document.addEventListener('pointerdown',event=>{
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const button=event.target.closest('button.btn,button.nav-item,button.tab');if(!button||button.disabled)return;
 button.querySelector('.press-wave')?.remove();const rect=button.getBoundingClientRect(),wave=document.createElement('span'),size=Math.max(rect.width,rect.height)*2;
 wave.className='press-wave';wave.setAttribute('aria-hidden','true');wave.style.width=wave.style.height=size+'px';wave.style.left=event.clientX-rect.left-size/2+'px';wave.style.top=event.clientY-rect.top-size/2+'px';button.append(wave);
 const animation=wave.animate([{transform:'scale(.1)',opacity:.23},{transform:'scale(1)',opacity:0}],{duration:500,easing:'cubic-bezier(.2,.6,.2,1)'});animation.finished.then(()=>wave.remove()).catch(()=>wave.remove());
});
